script:
// ph_logistik: Button „Packen“ → PH Lieferschein (Packtisch). Nur bei bezahlten/versandbereiten Bestellungen.
frappe.ui.form.on("PH Bestellung", {
	refresh(frm) {
		if (frm.is_new()) return;
		if (frm.doc.ph_logistik_lieferschein) {
			frm.add_custom_button(__("Lieferschein öffnen"), () => frappe.set_route("Form", "PH Lieferschein", frm.doc.ph_logistik_lieferschein), __("Logistik"));
			frm.add_custom_button(__("Packtisch"), () => frappe.set_route("ph-packtisch", { lieferschein: frm.doc.ph_logistik_lieferschein }), __("Logistik"));
			return;
		}
		if (["bezahlt", "versandbereit", "reserviert", "abholbereit"].includes(frm.doc.status)) {
			frm.add_custom_button(__("Packen (Lieferschein)"), () => {
				frappe.call({ method: "ph_logistik.api.lieferschein_aus_bestellung", args: { bestellung: frm.doc.name }, freeze: true }).then((r) => {
					if (r.message) frappe.set_route("ph-packtisch", { lieferschein: r.message });
				});
			}, __("Logistik"));
		}
	},
});

// ph_logistik: Button „Lieferschein erzeugen“ (Teillieferung möglich) aus der Auftragsbestätigung.
frappe.ui.form.on("PH Auftragsbestaetigung", {
	refresh(frm) {
		if (frm.is_new() || ["Storniert", "Abgerechnet"].includes(frm.doc.status)) return;
		frm.add_custom_button(__("Lieferschein erzeugen"), () => {
			const zeilen = (frm.doc.positionen || []).filter((p) => !p.art || ["Produkt", "Leistung"].includes(p.art));
			const d = new frappe.ui.Dialog({
				title: __("Lieferschein aus Auftrag"),
				fields: [
					{ fieldname: "lieferart", fieldtype: "Select", label: __("Lieferart"), options: ["Eigenlieferung", "Spedition", "Versand", "Abholung"], default: "Eigenlieferung", reqd: 1 },
					{ fieldname: "positionen", fieldtype: "Table", label: __("Mengen (0 = nicht liefern)"), cannot_add_rows: true, in_place_edit: true, data: zeilen.map((p) => ({ zeile: p.name, beschreibung: p.beschreibung || p.produkt, menge: (p.menge || 0) - (p.lieferschein_menge || 0) })), fields: [
						{ fieldname: "zeile", fieldtype: "Data", label: __("Zeile"), read_only: 1, in_list_view: 1 },
						{ fieldname: "beschreibung", fieldtype: "Data", label: __("Position"), read_only: 1, in_list_view: 1 },
						{ fieldname: "menge", fieldtype: "Int", label: __("Menge"), in_list_view: 1 },
					] },
				],
				primary_action_label: __("Anlegen"),
				primary_action(v) {
					const pos = {};
					(v.positionen || []).forEach((p) => { pos[p.zeile] = p.menge || 0; });
					d.hide();
					frappe.call({ method: "ph_logistik.api.lieferschein_aus_auftrag", args: { auftrag: frm.doc.name, positionen: pos, lieferart: v.lieferart }, freeze: true }).then((r) => r.message && frappe.set_route("Form", "PH Lieferschein", r.message));
				},
			});
			d.show();
		}, __("Logistik"));
	},
});

// ph_logistik: Button „Retourenlabel erzeugen“ (LetMeShip, Adressen getauscht) an der Retoure.
frappe.ui.form.on("PH Retoure", {
	refresh(frm) {
		if (frm.is_new()) return;
		if (frm.doc.ph_logistik_retourenlabel) {
			frm.add_custom_button(__("Retourenlabel öffnen"), () => frappe.set_route("Form", "PH Sendung", frm.doc.ph_logistik_retourenlabel), __("Logistik"));
			return;
		}
		frm.add_custom_button(__("Retourenlabel erzeugen"), () => {
			frappe.confirm(__("Retourenlabel über LetMeShip buchen und an die Retoure hängen?"), () => {
				frappe.call({ method: "ph_logistik.api.retourenlabel", args: { retoure: frm.doc.name }, freeze: true }).then((r) => { if (r.message) { frappe.show_alert({ message: __("Sendung {0}", [r.message]), indicator: "green" }); frm.reload_doc(); } });
			});
		}, __("Logistik"));
	},
});
